  let raw_volume_ratio_j = max(volume_ratio_j, 1.0e-9);
  let raw_current_volume_m3 = max(rest_volume_m3 * raw_volume_ratio_j, 0.0);
  let rest_particle_radius_m = radius_from_volume_m(rest_volume_m3);
