  local_vertex_offset: u32,
  surface_index: u32,
  material_id: f32,
  phase_id: f32,
  optical_state_id: f32,
  source_voxel_index: u32,
  isolation: f32,
  outward_hint: vec3<f32>,
  a: vec3<f32>,
  b: vec3<f32>,
  c: vec3<f32>
